const moments = [
  { name: "Birthdays", line: "Because they deserved a frame, not a forward.", label: "18th birthday", gradient: "linear-gradient(135deg,#f0c8a0,#d0a070)" },
  { name: "Friendships", line: "The photo you've been meaning to print since 2022.", label: "since day one", gradient: "linear-gradient(135deg,#c8d4f0,#a0b4e0)" },
  { name: "Travel", line: "Somewhere that deserves to exist off your camera roll.", label: "Amalfi, Italy", gradient: "linear-gradient(135deg,#a8c8a0,#78a870)" },
  { name: "Anniversaries", line: "The kind of gift kept in a drawer for all the right reasons.", label: "three years ✦", gradient: "linear-gradient(135deg,#f0d0c0,#d0a090)" },
  { name: "Milestones", line: "You were there. Now prove it.", label: "we made it", gradient: "linear-gradient(135deg,#d4c0e8,#b0a0d0)" },
  { name: "Just because", line: "No occasion. Just the feeling.", label: "just because", gradient: "linear-gradient(135deg,#f0e8c0,#d0c890)" },
];

export default function MomentsSection() {
  return (
    <section className="py-[100px] max-md:py-20 px-12 max-md:px-6 bg-[var(--cream-deep)]" id="moments">
      <div className="text-center px-12 max-md:px-6 mb-12 reveal">
        <h2 className="font-[Cormorant_Garamond] text-[46px] max-md:text-[32px] font-light italic mb-3">
          Made for the moments
          <br />
          that deserve more than a text.
        </h2>
      </div>

      <div className="grid grid-cols-3 max-md:grid-cols-2 gap-4 max-w-[900px] mx-auto reveal">
        {moments.map((m) => (
          <div
            key={m.name}
            className="bg-white border border-[var(--border)] rounded-2xl p-6 transition-all duration-200 hover:-translate-y-[3px] hover:shadow-[0_12px_32px_rgba(0,0,0,.08)]"
          >
            <div className="mb-4">
              <div className="w-full bg-white shadow-[0_4px_16px_rgba(0,0,0,.08)] rounded-sm">
                <div
                  className="mx-[6px] mt-[6px] h-[70px] rounded-[1px]"
                  style={{ background: m.gradient }}
                />
                <div className="h-6 flex items-center justify-center">
                  <span className="font-[DM_Mono] text-[9px] text-[#9a8878] tracking-[.06em]">
                    {m.label}
                  </span>
                </div>
              </div>
            </div>
            <div className="text-sm font-medium mb-1">{m.name}</div>
            <div className="text-xs font-light text-[var(--text-2)] leading-[1.5]">
              {m.line}
            </div>
          </div>
        ))}
      </div>
    </section>
  );
}
