const steps = [
  {
    num: "01",
    title: "Design it",
    copy: "Upload your photo. Choose a frame, write a caption only you would write, add the song that was playing when it happened.",
  },
  {
    num: "02",
    title: "We print it",
    copy: "Order a physical print — a single polaroid, a gift pack of 10, or a full event set. Premium glossy stock, shipped in 3–5 days.",
  },
  {
    num: "03",
    title: "They feel it",
    copy: "They open something you made. Not ordered. Not forwarded. Made. That's the whole difference.",
  },
];

export default function StepsSection() {
  return (
    <section className="py-[100px] max-md:py-20 px-12 max-md:px-6 bg-[var(--cream)]" id="how">
      <div className="text-center px-12 max-md:px-6 mb-12 reveal">
        <h2 className="font-[Cormorant_Garamond] text-[46px] max-md:text-[32px] font-light italic">
          Three steps.{" "}
          <em className="font-[Cormorant_Garamond] italic font-light">
            One feeling.
          </em>
        </h2>
      </div>

      <div className="grid grid-cols-3 max-md:grid-cols-1 gap-8 max-w-[900px] mx-auto reveal">
        {steps.map((s) => (
          <div key={s.num} className="text-center py-8 px-6">
            <div className="font-[Cormorant_Garamond] text-[56px] font-light italic text-[var(--brown-light)] leading-none mb-4">
              {s.num}
            </div>
            <div className="text-base font-medium mb-[10px]">{s.title}</div>
            <p className="text-[13px] font-light text-[var(--text-2)] leading-[1.65]">
              {s.copy}
            </p>
          </div>
        ))}
      </div>

      <div className="text-center mt-4">
        <span className="font-[DM_Mono] text-[11px] text-[var(--text-3)] tracking-[.04em]">
          ✦ You can also download your design for free. The print is optional.
        </span>
      </div>
    </section>
  );
}
