const plans = [
  {
    name: "Digital",
    amount: "Free",
    note: "forever free",
    features: ["High-res PNG download", "All 9 templates", "Unlimited designs"],
    btnLabel: "Start designing →",
    btnStyle: "outline" as const,
  },
  {
    name: "Single Print",
    amount: (
      <>
        <sup className="text-xl align-super">₹</sup>79
      </>
    ),
    note: "per polaroid · free shipping",
    features: ["Premium glossy print", "Kraft sleeve + envelope", "3–5 day delivery"],
    btnLabel: "Order a print →",
    btnStyle: "solid" as const,
    featured: true,
  },
  {
    name: "Gift Pack",
    amount: (
      <>
        <sup className="text-xl align-super">₹</sup>349
      </>
    ),
    note: "from · 5 polaroids",
    features: ["5, 10 or 20 polaroids", "Kraft gift box", "Perfect for any occasion"],
    btnLabel: "Build a pack →",
    btnStyle: "outline" as const,
  },
];

export default function PricingSection() {
  return (
    <section className="py-[100px] max-md:py-20 px-12 max-md:px-6 bg-[var(--cream-deep)]" id="pricing">
      <div className="text-center px-12 max-md:px-6 mb-12 reveal">
        <h2 className="font-[Cormorant_Garamond] text-[46px] max-md:text-[32px] font-light italic">
          The editor is always{" "}
          <em className="font-[Cormorant_Garamond] italic font-light">free.</em>
        </h2>
        <p className="text-[15px] font-light text-[var(--text-2)]">
          Pay only when you want it in your hands.
        </p>
      </div>

      <div className="grid grid-cols-3 max-md:grid-cols-1 gap-4 max-w-[820px] mx-auto mt-8 reveal">
        {plans.map((p) => (
          <div
            key={p.name}
            className={`bg-white border rounded-[20px] p-7 px-6 relative transition-transform duration-200 hover:-translate-y-[2px] ${
              p.featured
                ? "border-[var(--brown)] shadow-[0_8px_32px_rgba(139,99,71,.12)] scale-[1.02]"
                : "border-[var(--border)]"
            }`}
          >
            <div className="text-[13px] font-medium uppercase tracking-[.08em] text-[var(--text-2)] mb-2">
              {p.name}
            </div>
            <div className="font-[Cormorant_Garamond] text-[44px] font-light leading-none mb-1">
              {p.amount}
            </div>
            <div className="font-[DM_Mono] text-[11px] text-[var(--text-3)] mb-5">
              {p.note}
            </div>
            <ul className="list-none mb-6">
              {p.features.map((f) => (
                <li
                  key={f}
                  className="text-[13px] font-light text-[var(--text-2)] py-[5px] border-b border-[var(--border)] flex items-center gap-2"
                >
                  <span className="text-[9px] text-[var(--brown-light)]">✦</span>
                  {f}
                </li>
              ))}
            </ul>
            <button
              className={`w-full font-[DM_Sans] text-sm font-medium rounded-full py-3 cursor-pointer transition-all duration-200 ${
                p.btnStyle === "solid"
                  ? "bg-[var(--brown)] text-white border-none hover:bg-[#7a5540]"
                  : "bg-transparent text-[var(--text)] border border-[var(--border)] hover:bg-[var(--cream)]"
              }`}
            >
              {p.btnLabel}
            </button>
          </div>
        ))}
      </div>

      <div className="text-center mt-5">
        <span className="font-[DM_Mono] text-[11px] text-[var(--text-3)] tracking-[.04em]">
          ✦ Event orders (weddings · parties · corporate) — write to us
        </span>
      </div>
    </section>
  );
}
