import Link from "next/link";

export default function FinalCTA() {
  return (
    <section
      className="bg-[var(--dark)] min-h-screen flex flex-col items-center justify-center py-20 px-12 max-md:px-6 text-center"
      id="editor"
    >
      {/* Floating polaroid */}
      <div className="bg-white w-[200px] shadow-[0_16px_60px_rgba(0,0,0,.3)] rounded-[3px] mb-12 animate-[float2_6s_ease-in-out_infinite]">
        <div className="h-[176px] mx-3 mt-3 bg-gradient-to-br from-[#d4c0a8] to-[#a88068]" />
        <div className="h-[22px] flex items-center justify-center pt-1">
          <span className="font-[Dancing_Script] text-base text-[#3a2a1a]">
            your name here
          </span>
        </div>
        <div className="h-7 flex items-center justify-center">
          <span className="font-[DM_Mono] text-[9px] text-[#9a8878] tracking-[.08em]">
            the moment you made this
          </span>
        </div>
      </div>

      <div className="font-[DM_Mono] text-[11px] tracking-[.15em] text-[rgba(242,237,228,.35)] uppercase mb-5">
        ✦ start here
      </div>
      <div className="font-[Cormorant_Garamond] text-[58px] max-md:text-[38px] font-light italic text-[var(--cream)] leading-[1.1] max-w-[560px] mb-10">
        Make something
        <br />
        they&apos;ll keep forever.
      </div>
      <Link
        href="/editor"
        className="font-[DM_Sans] text-base font-medium bg-[var(--brown)] text-white border-none rounded-full py-4 px-10 cursor-pointer transition-all duration-200 no-underline inline-block hover:bg-[#7a5540] hover:-translate-y-[2px] hover:shadow-[0_8px_24px_rgba(139,99,71,.28)]"
      >
        Open the Editor →
      </Link>
      <div className="font-[DM_Mono] text-[11px] text-[rgba(242,237,228,.35)] mt-4 tracking-[.04em]">
        No account needed. Free to design.
      </div>
    </section>
  );
}
