"use client";

import { useEffect, useRef, useState } from "react";
import Link from "next/link";
import Logo from "@/components/ui/Logo";

export default function Navbar() {
  const [scrolled, setScrolled] = useState(false);
  const [menuOpen, setMenuOpen] = useState(false);
  const [activeSection, setActiveSection] = useState("");
  const navRef = useRef<HTMLElement>(null);

  useEffect(() => {
    const sections = ["templates", "moments", "how", "pricing"]
      .map((id) => document.getElementById(id))
      .filter(Boolean) as HTMLElement[];

    function onScroll() {
      setScrolled(window.scrollY > 24);
      const y = window.scrollY + 140;
      let active = "";
      for (const s of sections) {
        if (s.offsetTop <= y) active = s.id;
      }
      setActiveSection(active);
    }

    window.addEventListener("scroll", onScroll, { passive: true });
    onScroll();
    return () => window.removeEventListener("scroll", onScroll);
  }, []);

  const closeMenu = () => {
    setMenuOpen(false);
    document.body.style.overflow = "";
  };

  const toggleMenu = () => {
    const next = !menuOpen;
    setMenuOpen(next);
    document.body.style.overflow = next ? "hidden" : "";
  };

  const links = [
    { href: "#templates", label: "Templates", target: "templates" },
    { href: "#moments", label: "Moments", target: "moments" },
    { href: "#how", label: "How it works", target: "how" },
    { href: "#pricing", label: "Pricing", target: "pricing" },
  ];

  return (
    <>
      <nav
        ref={navRef}
        className={`fixed top-0 left-0 right-0 z-[100] px-8 grid grid-cols-[1fr_auto_1fr] items-center gap-6 transition-all duration-250 ${
          scrolled
            ? "py-[10px] bg-[rgba(242,237,228,0.92)] border-b border-[rgba(26,23,20,0.08)] shadow-[0_1px_0_rgba(255,255,255,.4)_inset]"
            : "py-[14px] bg-[rgba(242,237,228,0.72)] border-b border-transparent"
        } backdrop-blur-[14px] saturate-[1.05]`}
      >
        {/* Left */}
        <div className="flex items-center gap-[10px]">
          <Logo />
        </div>

        {/* Center links */}
        <div className="hidden md:flex items-center gap-1 justify-self-center bg-white/35 border border-[rgba(26,23,20,0.06)] rounded-full p-[5px]">
          {links.map((l) => (
            <a
              key={l.target}
              href={l.href}
              className={`relative font-[DM_Sans] text-[13.5px] font-normal no-underline px-4 py-2 rounded-full transition-all duration-150 tracking-[.005em] ${
                activeSection === l.target
                  ? "text-[var(--text)] bg-white shadow-[0_1px_2px_rgba(26,23,20,.05),0_4px_12px_rgba(26,23,20,.04)]"
                  : "text-[var(--text-2)] hover:text-[var(--text)]"
              }`}
            >
              {l.label}
            </a>
          ))}
        </div>

        {/* Right */}
        <div className="flex items-center gap-[14px] justify-self-end">
          <Link
            href="/auth"
            className="hidden md:block font-[DM_Sans] text-[13.5px] font-normal text-[var(--text-2)] no-underline px-1 py-2 transition-colors duration-150 hover:text-[var(--text)]"
          >
            Sign in
          </Link>
          <Link
            href="/editor"
            className="hidden md:inline-flex font-[DM_Sans] text-[13.5px] font-medium bg-[var(--brown)] text-white border-none rounded-full py-[10px] pl-[22px] pr-5 cursor-pointer transition-all duration-200 items-center gap-2 tracking-[.005em] whitespace-nowrap no-underline hover:bg-[#7a5540] hover:-translate-y-[1px] hover:shadow-[0_6px_18px_rgba(139,99,71,.28)] group"
          >
            Open Editor{" "}
            <span className="inline-block transition-transform duration-250 group-hover:translate-x-[3px]">
              →
            </span>
          </Link>
          <button
            className="md:hidden inline-flex w-[38px] h-[38px] border border-[rgba(26,23,20,0.12)] bg-white/40 rounded-full cursor-pointer items-center justify-center p-0"
            onClick={toggleMenu}
            aria-label="Menu"
          >
            <span
              className={`block w-4 h-[1.2px] bg-[var(--text)] relative transition-all duration-250 ${
                menuOpen ? "!bg-transparent" : ""
              }`}
            >
              <span
                className={`absolute left-0 w-4 h-[1.2px] bg-[var(--text)] transition-all duration-250 ${
                  menuOpen
                    ? "!top-0 rotate-45"
                    : "-top-[5px]"
                }`}
              />
              <span
                className={`absolute left-0 w-4 h-[1.2px] bg-[var(--text)] transition-all duration-250 ${
                  menuOpen
                    ? "!top-0 -rotate-45"
                    : "top-[5px]"
                }`}
              />
            </span>
          </button>
        </div>
      </nav>

      {/* Mobile menu */}
      <aside
        className={`fixed top-0 right-0 h-screen z-[99] bg-[var(--cream)] border-l border-[var(--border)] pt-[88px] px-7 pb-8 flex flex-col gap-1 shadow-[-20px_0_60px_rgba(26,23,20,.06)] transition-transform duration-350 ${
          menuOpen
            ? "translate-x-0"
            : "translate-x-full"
        }`}
        style={{ width: "min(86vw, 340px)" }}
      >
        {links.map((l) => (
          <a
            key={l.target}
            href={l.href}
            onClick={closeMenu}
            className="font-[Cormorant_Garamond] text-[28px] font-light text-[var(--text)] no-underline py-[14px] border-b border-[var(--border)]"
          >
            {l.label}
          </a>
        ))}
        <Link
          href="/auth"
          onClick={closeMenu}
          className="font-[Cormorant_Garamond] text-[28px] font-light text-[var(--text)] no-underline py-[14px] border-b border-[var(--border)]"
        >
          Sign in
        </Link>
        <Link
          href="/editor"
          onClick={closeMenu}
          className="mt-6 font-[DM_Sans] text-[15px] font-medium bg-[var(--brown)] text-white border-none rounded-full py-[14px] px-6 text-center no-underline"
        >
          Open Editor →
        </Link>
      </aside>

      {/* Backdrop */}
      {menuOpen && (
        <div
          className="fixed inset-0 bg-[rgba(26,23,20,.3)] z-[98] animate-[fadeIn_.3s_ease]"
          onClick={closeMenu}
        />
      )}
    </>
  );
}
