import Link from "next/link";
import PolaroidFloat from "@/components/ui/PolaroidFloat";

export default function HeroSection() {
  return (
    <section className="min-h-screen px-12 py-[120px] pb-20 grid grid-cols-1 md:grid-cols-2 gap-12 items-center relative overflow-hidden max-md:px-6 max-md:pt-[100px] max-md:pb-[60px] max-md:gap-10">
      <div>
        <div className="font-[DM_Mono] text-[11px] tracking-[.14em] text-[var(--text-3)] uppercase mb-5 flex items-center gap-2">
          ✦ design it yourself
        </div>
        <h1 className="font-[Cormorant_Garamond] text-[68px] max-md:text-[44px] font-light leading-[1.08] tracking-[-.01em] mb-6 opacity-0 animate-[fadeUp_.8s_ease_forwards_.1s]">
          Some gifts
          <br />
          are bought.
          <br />
          This one is <em className="italic text-[var(--brown)]">made.</em>
        </h1>
        <p className="text-[17px] font-light text-[var(--text-2)] leading-[1.75] max-w-[420px] mb-9 opacity-0 animate-[fadeUp_.8s_ease_forwards_.3s]">
          Design your own Polaroid. Add a caption only you would write, a song
          only you two know. Then hold it in your hands — or send it to theirs.
        </p>
        <div className="flex gap-3 items-center opacity-0 animate-[fadeUp_.8s_ease_forwards_.45s]">
          <Link
            href="/editor"
            className="font-[DM_Sans] text-[15px] font-medium bg-[var(--brown)] text-white border-none rounded-full py-[14px] px-8 cursor-pointer transition-all duration-200 no-underline inline-block hover:bg-[#7a5540] hover:-translate-y-[2px] hover:shadow-[0_8px_24px_rgba(139,99,71,.28)]"
          >
            Make Your First Polaroid →
          </Link>
          <button
            className="font-[DM_Sans] text-sm font-normal text-[var(--text-2)] bg-transparent border-none cursor-pointer underline underline-offset-[3px]"
            onClick={() =>
              document
                .getElementById("templates")
                ?.scrollIntoView({ behavior: "smooth" })
            }
          >
            See templates
          </button>
        </div>
      </div>

      {/* Floating polaroids */}
      <div className="relative h-[520px] max-md:h-[320px] opacity-0 animate-[fadeIn_.9s_ease_forwards_.5s]">
        <PolaroidFloat
          caption="always you"
          gradient="linear-gradient(135deg, #e8d5c0, #c4a882)"
          rotation="rotate(-4deg)"
          animation="float1 6s ease-in-out infinite"
          position="top:20px;left:40px"
          width="160px"
          imgHeight="138px"
        />
        <PolaroidFloat
          caption="26 · 04 · 2025"
          captionFont="mono"
          gradient="linear-gradient(135deg, #d4c5b0, #a89080)"
          rotation="rotate(3deg)"
          animation="float2 7s ease-in-out infinite .8s"
          position="top:60px;left:200px"
          width="155px"
          imgHeight="132px"
        />
        <PolaroidFloat
          showSpotify
          gradient="linear-gradient(160deg, #c8b8a0, #8b7060)"
          rotation="rotate(-2deg)"
          animation="float3 5.5s ease-in-out infinite 1.2s"
          position="top:220px;left:80px"
          width="175px"
          imgHeight="152px"
        />
        <PolaroidFloat
          caption="besties forever"
          gradient="linear-gradient(135deg, #e0ceb8, #b89878)"
          rotation="rotate(5deg)"
          animation="float4 8s ease-in-out infinite .4s"
          position="top:30px;left:360px"
          width="148px"
          imgHeight="125px"
          showTape
        />
      </div>
    </section>
  );
}
