interface PolaroidFloatProps {
  caption?: string;
  captionFont?: "script" | "mono";
  gradient: string;
  rotation: string;
  animation: string;
  position: string;
  width: string;
  imgHeight: string;
  showSpotify?: boolean;
  showTape?: boolean;
  className?: string;
}

export default function PolaroidFloat({
  caption,
  captionFont = "script",
  gradient,
  rotation,
  animation,
  position,
  width,
  imgHeight,
  showSpotify = false,
  showTape = false,
  className = "",
}: PolaroidFloatProps) {
  const fontClass =
    captionFont === "script"
      ? "font-[Dancing_Script] text-[15px] text-[#5a4a3a]"
      : "font-[DM_Mono] text-[10px] text-[#7a6e65] tracking-[.08em]";

  return (
    <div
      className={`absolute bg-white shadow-[0_12px_40px_rgba(0,0,0,.12)] rounded-[3px] transition-transform duration-300 hover:!rotate-0 hover:scale-[1.03] ${className}`}
      style={{
        width,
        transform: rotation,
        animation,
        ...parsePosition(position),
      }}
    >
      {showTape && (
        <div className="absolute -top-2 left-1/2 -translate-x-1/2 -rotate-[2deg] w-[55px] h-4 bg-[rgba(255,210,100,.55)] rounded-sm z-[2]" />
      )}
      <div
        className="mx-[10px] mt-[10px] rounded-[1px] overflow-hidden"
        style={{ height: imgHeight, background: gradient }}
      />
      {showSpotify && (
        <div className="h-[38px] flex items-center justify-center gap-[6px]">
          <div className="w-5 h-5 bg-[#1a1714] rounded-full flex items-center justify-center">
            <svg width="12" height="12" viewBox="0 0 24 24" fill="white">
              <path d="M12 0C5.4 0 0 5.4 0 12s5.4 12 12 12 12-5.4 12-12S18.66 0 12 0zm5.521 17.34c-.24.359-.66.48-1.021.24-2.82-1.74-6.36-2.101-10.561-1.141-.418.122-.779-.179-.899-.539-.12-.421.18-.78.54-.9 4.56-1.021 8.52-.6 11.64 1.32.42.18.479.659.301 1.02zm1.44-3.3c-.301.42-.841.6-1.262.3-3.239-1.98-8.159-2.58-11.939-1.38-.479.12-1.02-.12-1.14-.6-.12-.48.12-1.021.6-1.141C9.6 9.9 15 10.561 18.72 12.84c.361.181.54.78.241 1.2zm.12-3.36C15.24 8.4 8.82 8.16 5.16 9.301c-.6.179-1.2-.181-1.38-.721-.18-.601.18-1.2.72-1.381 4.26-1.26 11.28-1.02 15.721 1.621.539.3.719 1.02.419 1.56-.299.421-1.02.599-1.559.3z" />
            </svg>
          </div>
          <SpotifyBars />
        </div>
      )}
      {caption && !showSpotify && (
        <div className="flex items-center justify-center h-[38px]">
          <span className={fontClass}>{caption}</span>
        </div>
      )}
    </div>
  );
}

function SpotifyBars() {
  return (
    <div className="flex gap-[2px] items-center">
      {Array.from({ length: 18 }, (_, i) => (
        <div
          key={i}
          className="w-[2.5px] bg-[#1a1714] rounded-[1px]"
          style={{ height: `${6 + Math.sin(i * 0.8) * 5}px` }}
        />
      ))}
    </div>
  );
}

function parsePosition(pos: string): React.CSSProperties {
  const style: React.CSSProperties = {};
  const parts = pos.split(";").map((s) => s.trim());
  parts.forEach((p) => {
    const [key, val] = p.split(":").map((s) => s.trim());
    if (key === "top") style.top = val;
    if (key === "left") style.left = val;
    if (key === "right") style.right = val;
    if (key === "bottom") style.bottom = val;
  });
  return style;
}
