export default function DarkSection() {
  return (
    <section className="bg-[var(--dark)] py-[100px] px-12 max-md:px-6 text-center reveal">
      <div className="font-[DM_Mono] text-[11px] tracking-[.15em] text-[rgba(242,237,228,.4)] uppercase mb-8">
        the difference
      </div>
      <div className="font-[Cormorant_Garamond] text-[50px] max-md:text-[32px] font-light leading-[1.2] text-[var(--cream)] max-w-[760px] mx-auto mb-10">
        &ldquo;A polaroid they bought takes two seconds to forget.
        <br />
        <br />A polaroid{" "}
        <em className="italic text-[var(--brown-light)]">
          they made for you
        </em>
        <br />
        stays on the wall for years.&rdquo;
      </div>
      <div className="flex gap-3 justify-center flex-wrap">
        {["✦ made by you", "✦ felt by them", "✦ kept forever"].map((tag) => (
          <span
            key={tag}
            className="font-[DM_Mono] text-[11px] tracking-[.08em] text-[rgba(242,237,228,.5)] border border-[rgba(242,237,228,.2)] rounded-full py-[6px] px-4"
          >
            {tag}
          </span>
        ))}
      </div>
    </section>
  );
}
